fn handles_single_quote_character_as_value() {
    let content = "Q1=\"\nQ2='";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("Q1"), Some(&"\"".to_string()));
    assert_eq!(vars.get("Q2"), Some(&"'".to_string()));
}

#[test]
fn preserves_escaped_characters_in_double_quotes() {
    let content = r#"KEY="value with \"escaped\" quotes""#;

    let vars = EnvFileParser::parse(content).unwrap();

    // Parser does not interpret escape sequences; it strips outer quotes only
    assert_eq!(
        vars.get("KEY"),
        Some(&r#"value with \"escaped\" quotes"#.to_string())
    );
}

#[test]
fn preserves_escaped_characters_in_single_quotes() {
    let content = r"KEY='value with \'escaped\' quotes'";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(
        vars.get("KEY"),
        Some(&r"value with \'escaped\' quotes".to_string())
    );
}

