fn handles_quoted_value_containing_other_quote_type() {
    let content = "D=\"it's here\"\nS='he said \"hello\"'";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("D"), Some(&"it's here".to_string()));
    assert_eq!(vars.get("S"), Some(&"he said \"hello\"".to_string()));
}

